
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_pbe0_13_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_pbe0_13", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.933146497217177e+00, -2.877627077116645e+00, -2.799870461712466e+00, -2.692242731416928e+00, -2.545768987552921e+00, -2.351222732041101e+00, -2.101697091632973e+00, -1.797222799899659e+00, -1.450705625251308e+00, -1.088841115071385e+00, -7.358405296248165e-01, -5.106080241366112e-01, -4.473150721750734e-01, -3.659611808234108e-01, -2.627543087421125e-01, -1.655511335607270e-01, -8.910491935295474e-02, -3.301601074898511e-02, -7.207953407118891e-03, -8.108014326057201e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


